"""Freeze all scalar lower-case differences; invoke with pinned Python and -I."""

import argparse
import os
import subprocess
import sys
import unicodedata
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument('--scratch', type=Path, required=True)
parser.add_argument('--output', type=Path, required=True)
parser.add_argument('--context-output', type=Path)
args = parser.parse_args()
assert sys.flags.isolated and sys.version_info[:3] == (3, 12, 13), sys.version
assert unicodedata.unidata_version == '15.0.0'
args.scratch.mkdir(parents=True, exist_ok=True)
os.chdir(args.scratch)
source = args.scratch / 'lower_probe.rs'
source.write_text('''fn main() {
    println!("{:?}", char::UNICODE_VERSION);
    for cp in 0..=0x10ffff {
        if let Some(c) = char::from_u32(cp) {
            let lower: String = c.to_lowercase().collect();
            let probes = [format!("{c}Σ"), format!("A{c}Σ"), format!("AΣ{c}")];
            let mask = probes.iter().enumerate().fold(0, |mask, (i, s)| {
                let lower = s.to_lowercase();
                let final_sigma = if i == 2 { lower.chars().nth(1) == Some('ς') }
                                  else { lower.ends_with('ς') };
                mask | (u8::from(final_sigma) << i)
            });
            println!("P {cp:x} {mask}");
            if lower != c.to_string() {
                let points = lower.chars().map(|c| format!("{:x}", c as u32));
                println!("{cp:x} {}", points.collect::<Vec<_>>().join(","));
            }
        }
    }
}
''')
probe = args.scratch / ('lower_probe.exe' if os.name == 'nt' else 'lower_probe')
subprocess.run(['rustc', str(source), '-o', str(probe)], check=True)
lines = subprocess.check_output([str(probe)], text=True).splitlines()
assert lines.pop(0) == '(17, 0, 0)', 'Re-measure and review a changed Rust Unicode version'
probes = {int(cp, 16): int(mask) for _, cp, mask in
          (line.split() for line in lines if line.startswith('P '))}
lines = [line for line in lines if not line.startswith('P ')]
rust = dict((int(cp, 16), ''.join(chr(int(c, 16)) for c in lower.split(',')))
            for cp, lower in (line.split() for line in lines))
rows = []
for cp in range(0x110000):
    if 0xd800 <= cp <= 0xdfff:
        continue
    python_lower = chr(cp).lower()
    rust_lower = rust.get(cp, chr(cp))
    if python_lower != rust_lower:
        def escape(text):
            return '"' + ''.join('\\u{' + f'{ord(c):x}' + '}' for c in text) + '"'

        rows.append(f'    (0x{cp:x}, {escape(python_lower)}, {escape(rust_lower)}),')
args.output.write_text(
    '// Generated by generate_python312_lower.py; Python 3.12.13 -I.\n'
    '// Unicode 15.0.0 vs Rust 17.0.0.\n'
    '// Exhaustive scalar comparison; columns: input, Python lower, Rust lower.\n'
    '&[\n' + '\n'.join(rows) + '\n]\n'
)
print(f'{len(rows)} differences; {args.output}')

# Effective Cased excludes Case_Ignorable: the Final_Sigma rule ignores even
# characters with both properties. These three probes expose that precedence.
context_rows = []
for cp, rust_mask in probes.items():
    c = chr(cp)
    mask = (int((c + 'Σ').lower().endswith('ς'))
            | (int(('A' + c + 'Σ').lower().endswith('ς')) << 1)
            | (int(('AΣ' + c).lower()[1] == 'ς') << 2))
    assert mask in (3, 4, 6) and rust_mask in (3, 4, 6), (cp, mask, rust_mask)
    if mask != rust_mask:
        context_rows.append(f'    (0x{cp:x}, {mask}, {rust_mask}),')
context_output = args.context_output or args.output.with_name('python312-sigma.rs')
context_output.write_text(
    '// Generated by generate_python312_lower.py; Python 3.12.13 -I.\n'
    '// Unicode 15.0.0 vs Rust 17.0.0; exhaustive final-sigma probes.\n'
    '// Columns: scalar, Python mask, Rust mask. Bits: cΣ final, AcΣ final, AΣc final.\n'
    '// 3 = effective Cased, 6 = Case_Ignorable, 4 = neither.\n'
    '&[\n' + '\n'.join(context_rows) + '\n]\n'
)
print(f'{len(context_rows)} context differences; {context_output}')
